                        brandIdEquals(condition.getBrandId()),
                        isActiveEquals(condition.getIsActive()),
                        startDateAfter(condition.getStartDate()),
                        endDateBefore(condition.getEndDate()),
                        statusEquals(condition.getStatus())
                );

